// node mods/sotn-ultimate/tools/builder/node/test_stage_sprites.ts [stage...] [--work DIR]
// src/stage_sprites.ts against the current build's outputs of
// mods/sotn-ultimate/tools/gdn_assets.py / prs_assets.py sprites() (with rgdn_assets.py /
// rprs_assets.py) and of the asset tool's builds of them: every file it makes
// (assets/st/<st> JSONs, src/st/<st>/mod_*.h, gen/<block>.h, gen/us/sprites.c
// and sprite_banks.h, build/us/<st>_assets.us.yaml) byte for byte, then every
// array, against parseCArrays of src/st/<st>'s generated files (gen/** and
// the "Generated by" headers): the arrays it makes, and those it doesn't.
// Input: stage_assets.ts buildStage() as test_stage_assets.ts runs it (the
// converter's output in <work>/<st>/swapped, --work DIR or a temp folder
// made by stage_work.ts), the Saturn
// files from disks/saturn, the PS1 files from disks/us.
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { buildStage, modStageDir } from "../src/stage_assets.ts";
import { buildSprites } from "../src/stage_sprites.ts";
import { parseCArrays } from "./c_arrays.ts";
import type { CArray } from "./c_arrays.ts";
import { ROOT } from "./util.ts";
import { prepareSwapped } from "./stage_work.ts";

const args = process.argv.slice(2);
let workRoot = "";
const wi = args.indexOf("--work");
if (wi >= 0) {
    workRoot = args[wi + 1];
    args.splice(wi, 2);
}
if (!workRoot) {
    workRoot = fs.mkdtempSync(path.join(os.tmpdir(), "sotn_stage_work_"));
}
prepareSwapped(workRoot);
const stages = args.length ? args : ["gdn", "prs", "rgdn", "rprs"];
const rd = (dir: string) => (p: string): Uint8Array => new Uint8Array(fs.readFileSync(path.join(dir, p)));
const CONFIGS: Record<string, string> = { gdn: "mod_assets", prs: "mod_prs_assets", rgdn: "mod_rgdn_assets",
                                          rprs: "mod_rprs_assets" };
const gameH = ["include/game.h", "mods/sotn-ultimate/include/game_mod.h"]
    .map((f) => fs.readFileSync(path.join(ROOT, f), "utf8")).join("\n");
const wightPs1 = ["MOD_WIGHT_PS1_SPIRIT", "MOD_WIGHT_PS1_GLOW"].filter((s) => new RegExp(`^#define ${s}\\b`, "m").test(gameH));

function firstDiff(a: Uint8Array, b: Uint8Array): string {
    const n = Math.min(a.length, b.length);
    for (let i = 0; i < n; i++) {
        if (a[i] !== b[i]) {
            const ctx = (d: Uint8Array): string => JSON.stringify(new TextDecoder().decode(d.subarray(Math.max(0, i - 40), i + 40)));
            return `first difference at byte ${i}:\n      ts:     ${ctx(a)}\n      oracle: ${ctx(b)}`;
        }
    }
    return `sizes ${a.length} (ts) / ${b.length} (oracle), equal up to the shorter`;
}

function walk(dir: string): string[] {
    const out: string[] = [];
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
        const p = path.join(dir, e.name);
        if (e.isDirectory()) {
            out.push(...walk(p));
        } else {
            out.push(p);
        }
    }
    return out;
}

let bad = 0;
for (const st of stages) {
    const t0 = performance.now();
    const main = await buildStage(st, { work: rd(path.join(workRoot, st, "swapped")), saturn: rd(path.join(ROOT, "disks/saturn")),
                                        ps1Asset: rd(ROOT) });
    const r = await buildSprites(st, { saturn: rd(path.join(ROOT, "disks/saturn")), ps1: rd(path.join(ROOT, "disks/us")) },
                                 main, { assetConfig: fs.readFileSync(path.join(ROOT, "mods/sotn-ultimate/config", CONFIGS[st] + ".us.yaml"), "latin1"),
                                         wightPs1 });
    console.log(`=== ${st}: ${r.files.size} files, ${r.arrays.size} arrays, ${r.blocks.length} cmpgfx blocks, ` +
                `${((performance.now() - t0) / 1000).toFixed(1)} s`);
    // the files
    let same = 0;
    for (const [p, mine] of [...r.files].sort((a, b) => (a[0] < b[0] ? -1 : 1))) {
        const oracle = path.join(ROOT, p);
        if (!fs.existsSync(oracle)) {
            console.log(`  ${p}: NO ORACLE FILE`);
            bad++;
            continue;
        }
        const want = new Uint8Array(fs.readFileSync(oracle));
        if (want.length === mine.length && want.every((v, i) => v === mine[i])) {
            same++;
        } else {
            bad++;
            console.log(`  ${p}: DIFFERS, ${firstDiff(mine, want)}`);
        }
    }
    console.log(`  files: ${same}/${r.files.size} identical`);
    // the arrays of the stage's generated files
    const dir = path.join(ROOT, modStageDir(st));
    const genFiles = [...walk(path.join(dir, "gen")),
        ...fs.readdirSync(dir).map((f) => path.join(dir, f))
            .filter((f) => fs.statSync(f).isFile() && fs.readFileSync(f, "utf8").slice(0, 200).includes("Generated by"))];
    const repo = new Map<string, [CArray, string]>();
    for (const f of genFiles) {
        for (const a of parseCArrays(f, [dir, path.join(ROOT, "include")])) {
            repo.set(a.name, [a, path.relative(dir, f)]);
        }
    }
    let asame = 0;
    let shown = 0;
    for (const [name, mine] of r.arrays) {
        const ref = repo.get(name);
        const ok = ref !== undefined && ref[0].size === mine.size && ref[0].values.length === mine.values.length &&
            ref[0].values.every((v, i) => v === mine.values[i]);
        if (ok) {
            asame++;
            continue;
        }
        bad++;
        if (shown++ < 10) {
            if (ref === undefined) {
                console.log(`  array ${name}: NOT IN THE REPO'S GENERATED FILES`);
            } else {
                const i = ref[0].values.findIndex((v, k) => v !== mine.values[k]);
                console.log(`  array ${name} (${ref[1]}): DIFFERS: size ${mine.size}/${ref[0].size}, ` +
                            `${mine.values.length}/${ref[0].values.length} values, first at ${i} ` +
                            `(ts ${mine.values[i]}, repo ${ref[0].values[i]})`);
            }
        }
    }
    console.log(`  arrays: ${asame}/${r.arrays.size} identical`);
    // what this doesn't make: the repo's generated arrays by file, and stale
    // block files no build config lists
    const missing = new Map<string, string[]>();
    for (const [name, [, f]] of repo) {
        if (!r.arrays.has(name)) {
            missing.set(f, [...(missing.get(f) ?? []), name]);
        }
    }
    console.log(`  repo arrays not made here: ${[...missing].map(([f, n]) => `${f} (${n.length}: ${n.slice(0, 3).join(", ")}${n.length > 3 ? ", ..." : ""})`).join("; ") || "none"}`);
    const stale = fs.readdirSync(path.join(dir, "gen")).filter((f) => /^g_Mod.*\.h$/.test(f))
        .filter((f) => !r.files.has(`${modStageDir(st)}gen/${f}`));
    if (stale.length) {
        console.log(`  gen/ block files no longer in the build config (stale, unused): ${stale.join(", ")}`);
    }
}
console.log(bad ? `${bad} problems` : "all identical");
process.exit(bad ? 1 : 0);
